const VERIFICATION_REQUIRED_FOR = ['publish native listings','send buyer or seller messages','submit or respond to offers','invite trade participants'];
const SEARCH_STOP_WORDS = new Set(['a','an','and','find','for','good','in','looking','me','near','of','old','the','under','vintage','with']);
const SEARCH_SYNONYMS:Record<string,string[]> = {
  boat:['boat','boats','watercraft'],boats:['boat','boats','watercraft'],watercraft:['boat','boats','watercraft'],
  truck:['truck','trucks','pickup','4x4','4×4'],trucks:['truck','trucks','pickup','4x4','4×4'],pickup:['truck','trucks','pickup'],
  '4x4':['4x4','4×4','four wheel drive'],car:['car','cars','automobile'],cars:['car','cars','automobile'],
  camper:['camper','campers','rv','airstream'],campers:['camper','campers','rv','airstream'],
};

function db(){ return supabaseDatabase(); }

function searchTokens(query:string){
  return [...new Set(query.toLowerCase().replace(/[^a-z0-9×]+/g,' ').split(/\s+/).filter(token=>token&&!SEARCH_STOP_WORDS.has(token)))];
}

function inferCategory(query:string){
  const q=query.toLowerCase();
  if(/\b(boat|boats|watercraft|marine|sailboat)\b/.test(q))return 'Boats';
  if(/\b(car|cars|truck|trucks|pickup|4x4|4×4|jeep|automobile)\b/.test(q))return 'Cars & trucks';
  if(/\b(camper|campers|rv|airstream)\b/.test(q))return 'Campers';
  if(/\b(machine|machinery|lathe|tool)\b/.test(q))return 'Machinery';
  if(/\b(motorcycle|motorcycles|bike|panhead)\b/.test(q))return 'Motorcycles';
  return null;
}

function searchableListing(listing:any,sellerName=''){
  return `${listing.title} ${listing.category} ${listing.description} ${listing.location} ${listing.condition} ${listing.make??''} ${listing.model??''} ${sellerName} ${JSON.stringify(listing.attributes??{})}`.toLowerCase();
}

function matchesSearch(listing:any,input:Input,sellerName=''){
  const minPrice=Number(input.minPrice??0); const maxPrice=Number(input.maxPrice??Infinity);
  const afterYear=Number(input.afterYear??0); const beforeYear=Number(input.beforeYear??Infinity);
  const category=String(input.category??''); const condition=String(input.condition??''); const location=String(input.location??'').toLowerCase();
  if(Number(listing.price)<minPrice||Number(listing.price)>maxPrice)return false;
  if(Number(listing.year??0)<afterYear||Number(listing.year??0)>beforeYear)return false;
  if(category&&category!=='All'&&listing.category!==category)return false;
  if(condition&&String(listing.condition).toLowerCase()!==condition.toLowerCase())return false;
  if(location&&!String(listing.location).toLowerCase().includes(location))return false;
  const haystack=searchableListing(listing,sellerName);
  return searchTokens(String(input.query??'')).every(token=>(SEARCH_SYNONYMS[token]??[token]).some(term=>haystack.includes(term)));
}

function sortedPage(listings:any[],input:Input){
  const sort=String(input.sort??'relevance'); const ordered=[...listings];
  if(sort==='price_asc')ordered.sort((a,b)=>Number(a.price)-Number(b.price));
  if(sort==='price_desc')ordered.sort((a,b)=>Number(b.price)-Number(a.price));
  if(sort==='year_asc')ordered.sort((a,b)=>Number(a.year??0)-Number(b.year??0));
  if(sort==='year_desc')ordered.sort((a,b)=>Number(b.year??0)-Number(a.year??0));
  const pageSize=Math.min(100,Math.max(1,Number(input.pageSize??50))); const page=Math.max(1,Number(input.page??1)); const start=(page-1)*pageSize;
  return {total:ordered.length,page,pageSize,results:ordered.slice(start,start+pageSize),hasMore:start+pageSize<ordered.length};
}

const initializedUsers=new Map<string,Promise<void>>();

async function initializeUser(user:AppUser){
  const d1 = db();
  await d1.prepare(`INSERT INTO users (id,email,name,avatar,created_at) VALUES (?,?,?,?,?) ON CONFLICT DO NOTHING`).bind(user.userId,user.email,user.displayName,null,now()).run();
  await d1.prepare(`INSERT INTO user_preferences (user_id,preferences_json,updated_at) VALUES (?,?,?) ON CONFLICT DO NOTHING`).bind(user.userId,json(DEFAULT_INTERFACE_PREFERENCES),now()).run();
  await d1.prepare(`UPDATE activity_events SET actor_type='system',actor_name='Zingposts',summary='Example workspace created with seeded marketplace data.' WHERE action='seed_workspace'`).run();
  await d1.prepare(`UPDATE board_items SET notes='Seeded example collection' WHERE notes='Agent organized'`).run();
  const count = await d1.prepare(`SELECT COUNT(*) AS count FROM listings`).first<{count:number}>();
  if (Number(count?.count ?? 0) === 0) await seed(user);
  const workspace = await d1.prepare(`SELECT COUNT(*) AS count FROM activity_events WHERE user_id=? AND action='seed_workspace'`).bind(user.userId).first<{count:number}>();
  const boards = await d1.prepare(`SELECT COUNT(*) AS count FROM boards WHERE user_id=?`).bind(user.userId).first<{count:number}>();
  if(Number(workspace?.count??0)===0&&Number(boards?.count??0)===0) await seedUserWorkspace(user);
}

export async function ensureDatabase(user:AppUser){
  const existing=initializedUsers.get(user.userId);
  if(existing)return existing;
  const pending=initializeUser(user).catch((error)=>{initializedUsers.delete(user.userId);throw error;});
  initializedUsers.set(user.userId,pending);
  return pending;
}

