async function storedPreferences(user:AppUser) {
  const row=await db().prepare(`SELECT preferences_json FROM user_preferences WHERE user_id=?`).bind(user.userId).first<{preferences_json:string}>();
  return {...DEFAULT_INTERFACE_PREFERENCES,...parse<Record<string,unknown>>(row?.preferences_json,{})};
}

function verificationFrom(preferences:Record<string,unknown>) {
  const verifiedAt=typeof preferences.identityVerifiedAt==='string'?preferences.identityVerifiedAt:null;
  return {status:verifiedAt?'verified':'unverified',verifiedAt,method:verifiedAt?String(preferences.identityVerificationMethod??'account-reauthentication'):null,requiredFor:VERIFICATION_REQUIRED_FOR};
}

export async function getState(user:AppUser) {
  await ensureDatabase(user); const d1=db();
  const [listings,users,boards,boardItems,saved,alerts,research,conversations,messages,offers,trades,participants,assets,activities,confirmations,agents,preferences,collaborationSessions,collaborationItems] = await Promise.all([
    d1.prepare(`SELECT * FROM listings ORDER BY CASE status WHEN 'published' THEN 0 ELSE 1 END, updated_at DESC`).all(), d1.prepare(`SELECT id,email,name,avatar FROM users`).all(), d1.prepare(`SELECT * FROM boards WHERE user_id=? ORDER BY created_at`).bind(user.userId).all(), d1.prepare(`SELECT * FROM board_items`).all(), d1.prepare(`SELECT * FROM saved_items WHERE user_id=?`).bind(user.userId).all(), d1.prepare(`SELECT * FROM alerts WHERE user_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM research_notes WHERE user_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM conversations WHERE buyer_id=? OR seller_id=? ORDER BY updated_at DESC`).bind(user.userId,user.userId).all(), d1.prepare(`SELECT * FROM messages WHERE conversation_id IN (SELECT id FROM conversations WHERE buyer_id=? OR seller_id=?) ORDER BY created_at`).bind(user.userId,user.userId).all(), d1.prepare(`SELECT * FROM offers WHERE buyer_id=? OR listing_id IN (SELECT id FROM listings WHERE owner_id=?) ORDER BY updated_at DESC`).bind(user.userId,user.userId).all(), d1.prepare(`SELECT * FROM trade_rooms WHERE creator_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM trade_participants`).all(), d1.prepare(`SELECT * FROM trade_assets`).all(), d1.prepare(`SELECT * FROM activity_events WHERE user_id=? ORDER BY created_at DESC LIMIT 40`).bind(user.userId).all(), d1.prepare(`SELECT * FROM confirmation_requests WHERE user_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM agent_connections WHERE user_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT preferences_json FROM user_preferences WHERE user_id=?`).bind(user.userId).first<{preferences_json:string}>(), d1.prepare(`SELECT * FROM collaboration_sessions WHERE user_id=? ORDER BY updated_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM collaboration_items WHERE user_id=? ORDER BY created_at`).bind(user.userId).all(),
  ]);
  const mergedPreferences={...DEFAULT_INTERFACE_PREFERENCES,...parse<Record<string,unknown>>(preferences?.preferences_json,{})};
  return { user, preferences:mergedPreferences, verification:verificationFrom(mergedPreferences), listings:listings.results.map(hydrateListing), users:users.results, boards:boards.results, boardItems:boardItems.results, saved:saved.results, alerts:alerts.results.map(hydrateJson), research:research.results.map(hydrateJson), conversations:conversations.results, messages:messages.results, offers:offers.results, trades:trades.results, participants:participants.results, assets:assets.results.map(hydrateJson), activities:activities.results.map(hydrateJson), confirmations:confirmations.results.map(row=>{const item=hydrateJson(row);return {...item,summary:`Agent wants to ${String(item.action).replaceAll('_',' ')}.`};}), agents:agents.results.map(hydrateJson), collaborationSessions:collaborationSessions.results.map(hydrateJson), collaborationItems:collaborationItems.results.map(hydrateJson) };
}

function hydrateJson(row:Record<string,unknown>) {
  const out={...row};
  for (const key of ['criteria_json','sources_json','conditions_json','undo_json','payload_json','scopes_json','setup_json','context_json','listing_ids_json','options_json','response_json']) {
    if (!(key in out)) continue;
    if (key==='response_json'&&out[key]==null) { out.response=null; continue; }
    const fallback=key==='sources_json'||key==='conditions_json'||key==='scopes_json'||key==='listing_ids_json'||key==='options_json'?[]:{};
    out[key.replace('_json','')]=parse(out[key],fallback);
  }
  return out;
}
function hydrateListing(row:Record<string,unknown>) { return {...hydrateJson(row),attributes:parse(row.attributes_json,{})}; }

